// Answer a private message, at most once per COOLDOWN_HOURS per person. Messages in groups are skipped on purpose.
const COOLDOWN_HOURS = 1;

const event = msg.payload;
if (event.type !== 'message.received') {
    return null;
}
const data = event.data || {};
const sender = data.from || {};
if (data.to && data.to.group_id) {
    return null;
}
if (!sender.number) {
    return null;
}
const when = new Date(event.created_at || Date.now());
const answeredAt = flow.get('answeredAt') || {};
if (when.getTime() - (answeredAt[sender.number] || 0) < COOLDOWN_HOURS * 3600 * 1000) {
    return null;
}
answeredAt[sender.number] = when.getTime();
flow.set('answeredAt', answeredAt);
msg.to = '+' + sender.number;
msg.number = event.number_alias || 'main';
msg.payload = 'Thanks' + (sender.name ? ', ' + sender.name : '') + '. We received your message and will answer soon.';
return msg;
